        attemptedText: expectation?.edits?.[phase]}));
      report.readbackReplacement = {
        before: observed.getKeyboard?.after && pair(observed.getKeyboard.after),
        after: observed.readback && pair(observed.readback)};
    }
    try { assertBusiness(report, observed, input, expectation, A, finalDb); }
    catch (error) { report.assertions.push({name: 'assertion collection completed', passed: false, error: errorRecord(error)}); }
    report.finishedAt = now();
    report.passed = report.assertions.every(item => item.passed) &&
      !report.observationErrors.length && !report.environmentErrors.length &&
      !report.recordingErrors.length && !report.cleanupErrors.length;
    if (!persist('final')) {
      report.passed = false;
      // 记录写入失败时，将完整诊断留在 stderr 并报失败。
      // 不重试，也不把未落盘记录报作成功。
      process.stderr.write(JSON.stringify(report, null, 2) + '\n');
    }
    if (report.recordingErrors.length) report.passed = false;
    process.stdout.write(`${scenario}: ${report.passed ? 'PASS' : 'FAIL'}；完整记录：${recordPath}\n`);
  }
  const failures = report.assertions.filter(item => !item.passed).map(item => item.name);
  assert.equal(report.passed, true, `${scenario} 失败：${failures.join('; ')}；完整记录：${recordPath}`);
}

// 两个独立用例顺序运行，历史正常保存失败后仍执行 abort 观察。
// 每例都单独初始化完整三章。
await test('正常保存：完整A、POST等待、GET读回等待、恢复编辑及刷新历史',
  {concurrency: false, timeout: TEST_LIMIT}, () => runScenario('normal'));
await test('服务收到POST前abort：无服务POST/新增修订，保留A并先读当前稿',
  {concurrency: false, timeout: TEST_LIMIT}, () => runScenario('abort'));

